INSERT INTO `rz_audit_list` VALUES (658, 5, '1834109224649490400', 'wangxichen', '2024-09-13 11:35:31', '{\"id\": 5, \"uuid\": \"1834109224649490400\", \"remark\": null, \"comment\": \"二级阶段地块137.06亩（郑州市恒司置业有限公司、郑州市拓阜置业有限公司）土地已完成抵押担保，因受房地产市场的影响，暂未进行开发销售，未形成有效的收入进行还本付息，截至2024年9月已归还本金4195.23万元，利息约5183万元，按还款计划12月1日再还本12089万元，2025年归还本息约26502万元，还款压力较大。\", \"scrUuid\": 1834094800073130000, \"createBy\": \"wangxichen\", \"deadline\": \"2028-03-13\", \"loanTerm\": \"59.76\", \"updateBy\": null, \"startDate\": \"2023-03-20\", \"createTime\": \"2024-09-12 13:27:14\", \"loanAmount\": 814210399.9999999, \"rzsrc2List\": [], \"updateTime\": \"2024-09-12 13:58:10\", \"projectName\": \"小湖1号院\", \"managementId\": \"DHGL002\", \"borrowingUnit\": \"郑州市管开新城置业有限公司\", \"afterLoanState\": \"未完结\", \"quantitativeGoals\": \"2\", \"remainingQuantity\": 2, \"progressDescription\": \"二级地块未动工，暂无还款来源，现阶段已开始归还贷款本金，还款压力较大；郑州市恒司置业有限公司：83.47亩土地，豫（2024）郑州市不动产权第0094342号已完成抵押；郑州市拓阜置业有限公司：53.59亩土地，豫（2023）郑州市不动产权第0084639号已完成抵押。\", \"quantitativeContent\": \"匹配二级土地未开发\", \"financialInstitution\": \"工商银行郑州南阳路支行\", \"currentImplementation\": \"0\"}', 'rz_after_loan', '1759515025552179200', 'DHGL002|2024-09-13 11:35:30', NULL);
