-- ----------------------------
-- Table structure for rz_audit_list
-- ----------------------------
DROP TABLE IF EXISTS `rz_audit_list`;
CREATE TABLE `rz_audit_list`  (
  `id` int(0) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `audit_id` int(0) NULL DEFAULT NULL COMMENT '审核id',
  `uuid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据唯一编号,所有添加和修改的数据,都先存到这个表里,如果有uuid+审核状态是 待审批 的,就提示\"等待上次审核完成后,再提交新的修改\",审核通过之后再通过uuid和表名,去调用各自的接口,保存到最终的表里.关于uuid的更新时机,添加时,默认新生成uuid,修改时,使用旧uuid,审核通过去保存时,生成新的uuid保存回去.',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `data_json` json NULL COMMENT '数据json文件',
  `table_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '父级表名',
  `audit_state` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核状态：待审批、审批不通过、审批通过、已撤回,只有 待审批状态不能提交新的审核',
  `management_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '管理编号',
  `comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批情况说明',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `management_id`(`management_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 776 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rz_audit_list
-- ----------------------------

